/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls } from '../core/renderer';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { exChase } from './chase';
import { exShowChooser } from './chooser';
import { exNight, exNightBind, exNightStep } from './nightShows';
import { exMulti } from './multi';
import { CONFIG } from '../config';
import type { SwingController } from '../bridges/song-han/SwingController';

const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung

let glider: THREE.Group | null = null;
let state: GliderState | null = null;
let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi

const active = () => cam.mode === 'glider' && state !== null;

/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
function exShowSpeed(): void {
  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
  if (t === readout) return;
  readout = t;
  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
}

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!);
  exChase(camera, controls.target, state!, dt);
  exShowSpeed();
  exNightStep(dt);
  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
}

export const explore = {
  active,
  nightShows: exNight,
  get state() { return state; },
  get glider() { return glider; },
  start(): void {
    state = exCreate();
    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  update(dt: number): void {
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
    else location.replace(u.toString());
  },
};

export function setupExplore(ctrl: SwingController): void {
  exNightBind(ctrl);
  window.addEventListener('keydown', (e) => {
    if (!active()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
}
/* ============================ Tự khám phá: màn chọn phương tiện ============================
   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */

import { getLang, onChange } from '../i18n';
import { exMulti } from './multi';
import { exShowLobby } from './multi/lobby';

export type ExChoice = 'glider' | 'guided';

const el = () => document.getElementById('chooser');

/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
function lockGliderOnTouch(root: HTMLElement): void {
  if (!window.matchMedia('(hover: none)').matches) return;
  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
  if (!card) return;
  card.disabled = true;
  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
}

/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
function wireLang(root: HTMLElement): void {
  const mine = root.querySelector<HTMLSelectElement>('#exLang');
  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
  if (!mine || !main) return;
  mine.innerHTML = main.innerHTML; mine.value = getLang();
  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
  onChange((code) => { mine.value = code; });
}

/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
const inerted: HTMLElement[] = [];
function setUnderInert(root: HTMLElement, on: boolean): void {
  if (on) {
    for (const c of Array.from(document.body.children) as HTMLElement[]) {
      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
      c.inert = true; inerted.push(c);
    }
  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
}

export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: () => void = () => {}): void {
  const root = el();
  if (!root) return;
  lockGliderOnTouch(root);
  wireLang(root);
  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
    if (b.disabled) return;
    b.addEventListener('click', () => {
      const choice = b.dataset.pick as ExChoice;
      /* Dù lượn có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay một mình ngay như trước */
      if (choice === 'glider' && exMulti.begin(() => {})) {
        const solo = () => { exHideChooser(); onPick('glider'); };
        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(); }, onSolo: solo });
        return;
      }
      exHideChooser(); onPick(choice);
    }, { once: true });
  });
  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
  const loading = document.getElementById('loading');
  if (!loading || loading.classList.contains('done')) { show(); return; }
  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
}

export function exHideChooser(): void {
  const root = el();
  if (root) { root.hidden = true; setUnderInert(root, false); }
}
/* ===== Dù lượn nhiều người: điều phối phía khách =====
   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), nhãn tên và danh sách người bay.
   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
import { camera } from '../../core/renderer';
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exConnect } from './client';
import { MultiSession } from './session';
import { exRemotes } from './remote';
import { exLabelsUpdate, exLabelsClear } from './labels';
import type { GliderState } from '../flight';

const M = CONFIG.explore.multi;
let session: MultiSession | null = null;
let sentAt = -1e9;
let rosterKey = '';

/* Danh sách người bay ở góc màn hình: đầu "Đang bay n/5", mỗi người một dòng có chấm màu theo slot; dùng textContent */
function renderRoster(): void {
  const box = document.getElementById('exMpRoster');
  if (!box) return;
  const flyers = session ? session.flyers : [];
  const head = t('exMpFlying', { n: flyers.length });
  const key = flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + (session ? session.mySlot : -1) + '#' + head;
  if (key === rosterKey) return;
  rosterKey = key;
  box.hidden = !session || session.phase === 'solo';
  box.textContent = '';
  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
  for (const f of flyers) {
    const row = document.createElement('div'); row.className = 'ex-mp-row' + (session && f.slot === session.mySlot ? ' me' : '');
    const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
    const nm = document.createElement('span'); nm.textContent = f.name;
    row.append(dot, nm); box.appendChild(row);
  }
}

export const exMulti = {
  /* Địa chỉ máy chủ: ?multi= nếu có; ?test không có multi= thì rỗng (không mở mạng); còn lại cấu hình */
  url(): string {
    const q = new URLSearchParams(location.search);
    const u = q.get('multi');
    if (u !== null) return u;
    return q.has('test') ? '' : M.url;
  },
  get session(): MultiSession | null { return session; },
  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test

  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
  begin(onReady: () => void): boolean {
    const url = exMulti.url();
    if (!url || session) return false;
    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
    let ready = false;
    s.onPos = f => exRemotes.onPos(f, performance.now());
    s.onChange = () => {
      exRemotes.sync(s.flyers, s.mySlot);
      if (s.phase === 'solo') exLabelsClear();
      renderRoster();
      exMulti.onChange();
      if (!ready) { ready = true; onReady(); }
    };
    s.open();
    return true;
  },

  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
  update(_dt: number, nowMs: number, state: GliderState | null): void {
    if (!session) return;
    exRemotes.update(nowMs);
    exLabelsUpdate(camera, exRemotes, nowMs);
    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
      sentAt = nowMs;
      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank));
    }
  },

  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
  watchState(): GliderState | null {
    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
  }
};

onLang(() => { rosterKey = ''; renderRoster(); });
/* ===== Dù lượn nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
   Hiện sau khi bấm thẻ Dù lượn lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người đang bay, ô tên, nút Bay ngay.
   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến + nút Bay một mình.
   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm). */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exMulti } from './index';
import { exSanitizeName } from './protocol';
import type { MultiSession } from './session';

export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void }

const M = CONFIG.explore.multi;
const NAME_KEY = 'exMpName';
const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }

let listKey = '';
let langBound = false;
let redraw: (() => void) | null = null;

/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
  const input = $<HTMLInputElement>('exMpNameIn'), fly = $<HTMLButtonElement>('exMpFly'), solo = $<HTMLButtonElement>('exMpSolo');
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
  $('exTitle').hidden = true;
  box.setAttribute('aria-labelledby', 'exMpSky');
  root.hidden = false;
  if (!input.value) input.value = loadName();
  listKey = '';
  let done = false;
  const finish = (f: () => void) => { if (done) return; done = true; exMulti.onChange = () => {}; redraw = null; f(); };

  const render = () => {
    if (done) return;
    const ph = session.phase;
    if (ph === 'flying') { finish(cb.onFly); return; }
    if (ph === 'watching') { finish(cb.onWatch); return; }
    const offline = ph === 'solo';
    $('exMpOnline').hidden = offline;
    $('exMpOffline').hidden = !offline;
    solo.hidden = !offline;
    if (offline) { if (document.activeElement !== solo) solo.focus({ preventScroll: true }); return; }
    const ready = ph === 'lobby';
    const free = M.slots - session.flyers.length;
    $('exMpSeats').textContent = ready ? t('exMpSeats', { n: free }) : '…';
    $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
    const taken = new Set(session.flyers.map(f => f.slot));
    $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
      d.classList.toggle('on', taken.has(i));
      d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
    });
    const key = session.flyers.map(f => f.slot + ':' + f.name).join('|');
    if (key !== listKey) {
      listKey = key;
      const list = $('exMpList'); list.textContent = '';
      for (const f of session.flyers) {
        const row = document.createElement('div'); row.className = 'ex-mp-row';
        const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
        const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
        row.append(dot, nm); list.appendChild(row);
      }
    }
    $('exMpNameBad').hidden = session.notice !== 'nameBad';
    fly.disabled = !ready || exSanitizeName(input.value) === null;
  };

  const go = () => {
    const name = exSanitizeName(input.value);
    if (name === null || session.phase !== 'lobby') return;
    saveName(name);
    session.join(name);
  };
  input.addEventListener('input', () => {
    $('exMpNameBad').hidden = true;
    const ok = exSanitizeName(input.value);
    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
    fly.disabled = session.phase !== 'lobby' || ok === null;
  });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
  fly.addEventListener('click', go);
  solo.addEventListener('click', () => finish(cb.onSolo), { once: true });

  redraw = render;
  if (!langBound) { langBound = true; onLang(() => { if (redraw) redraw(); }); }
  exMulti.onChange = render;
  render();
  input.focus({ preventScroll: true });
}
/* ===== Dù lượn nhiều người: máy trạng thái phiên (không DOM, không three) ===== */
import type { Flyer, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  mySlot = -1;
  watched = -1;       // slot đang xem, -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n)) {}

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  join(name: string): void {
    this.name = name; this.notice = '';
    this.t?.send({ t: 'join', name });
  }

  // Rời chỗ bay (do idle): trả slot, chuyển sang xem
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.toWatching();
    this.onChange();
  }

  sendPos(x: number, y: number, z: number, yaw: number, bank: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
  private fixWatched(): void {
    const ids = this.flyers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < multiParams.slots;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  private recv(m: ServerMsg): void {
    if (this.disposed) return;
    switch (m.t) {
      case 'lobby':
        this.flyers = m.flyers;
        if (this.first) {
          this.first = false;
          if (m.flyers.length >= multiParams.slots) this.phase = 'watching';
          else this.phase = 'lobby';
        }
        // đang bay: danh sách chỉ để hiển thị
        this.fixWatched();
        break;
      case 'joined':
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
        this.fixWatched();
        break;
      case 'rejected':
        if (m.why === 'name') this.notice = 'nameBad';
        else {
          if (this.phase === 'watching') this.notice = 'late';
          else { this.phase = 'watching'; }
          this.fixWatched();
        }
        break;
      case 'pos':
        this.onPos(m.f);
        return;
      case 'released':
        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
        break;
    }
    this.onChange();
  }
}
/* ===== Dù lượn nhiều người: dù của người bay cùng =====
   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
   Vị trí nhận 5 lần/s được nội suy, lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { CONFIG } from '../../config';
import { exBuildGlider, exPlaceGlider } from '../glider';
import type { GliderState } from '../flight';
import { ExTrack, type ExPose } from './interp';
import type { Flyer } from './protocol';

const M = CONFIG.explore.multi;

interface RemoteSlot {
  name: string | null;        // null = slot trống
  group: THREE.Group | null;
  track: ExTrack;
  pose: ExPose;               // đệm lấy mẫu
  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
  live: boolean;              // đã có mẫu và đang hiện
}

const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
}));
let me = -1;

function hide(s: RemoteSlot): void {
  s.track.reset(); s.live = false;
  if (s.group) s.group.visible = false;
}

export const exRemotes = {
  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
  sync(flyers: Flyer[], mySlot: number): void {
    me = mySlot;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      let name: string | null = null;
      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
      if (name === null) { s.name = null; hide(s); continue; }
      if (name !== s.name) {
        s.name = name; hide(s);
        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ vào phản chiếu nước, giữ draw call ≈ 1 mỗi dù
      }
    }
  },

  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank]; chỉ nhận slot đã biết chủ và không phải của mình */
  onPos(f: number[][], nowMs: number): void {
    for (const e of f) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.name === null) continue;
      s.track.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
    }
  },

  update(nowMs: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (const s of slots) {
      if (s.name === null || !s.group) continue;
      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
      const p = s.pose;
      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
      exPlaceGlider(s.group, s.state);
      s.group.visible = s.live = true;
    }
  },

  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
  slotState(slot: number): GliderState | null {
    const s = slots[slot];
    return s && s.live ? s.state : null;
  },

  /* Dù và tên của slot (cho nhãn tên và test); null nếu slot trống */
  group(slot: number): THREE.Group | null { const s = slots[slot]; return s && s.name !== null ? s.group : null; },
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
  clear(): void {
    me = -1;
    for (const s of slots) { s.name = null; hide(s); }
  }
};
/* ===== Dù lượn nhiều người: nhãn tên nổi dưới cánh dù người khác =====
   Một div cho mỗi slot trong #exMpLabels. Điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù), ẩn khi sau camera hoặc slot chưa hiện.
   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import type { exRemotes } from './remote';

const M = CONFIG.explore.multi;
interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
let labs: Lab[] | null = null;
const _v = new THREE.Vector3();

function init(): Lab[] | null {
  const box = document.getElementById('exMpLabels');
  if (!box) return null;
  return Array.from({ length: M.slots }, () => {
    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
  });
}

// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;

export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number): void {
  if (!labs && !(labs = init())) return;
  const w = window.innerWidth, h = window.innerHeight;
  for (let i = 0; i < labs.length; i++) {
    const L = labs[i], st = remotes.slotState(i);
    let vis = false;
    if (st) {
      _v.set(st.pos.x, st.pos.y - M.labelBelow, st.pos.z).applyMatrix4(camera.matrixWorldInverse);
      if (-_v.z > 0.1) {   // trước camera
        _v.applyMatrix4(camera.projectionMatrix);
        const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
        if (px > -80 && px < w + 80 && py > -40 && py < h + 40) {
          vis = true;
          if (nowMs - L.tMs >= 200) {
            L.tMs = nowMs;
            const txt = `${remotes.name(i)} · ${dist(Math.hypot(st.pos.x - camera.position.x, st.pos.y - camera.position.y, st.pos.z - camera.position.z))}`;
            if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
          }
          if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
        }
      }
    }
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
}

/* Ẩn hết nhãn (rời phòng) */
export function exLabelsClear(): void {
  if (!labs) return;
  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
}

